package staking

import (
	"fmt"
	"math/big"

	"github.com/xgr-network/xgr-node/chain"
	"github.com/xgr-network/xgr-node/helper/common"
	"github.com/xgr-network/xgr-node/helper/hex"
	"github.com/xgr-network/xgr-node/helper/keccak"
	"github.com/xgr-network/xgr-node/state"
	"github.com/xgr-network/xgr-node/types"
	"github.com/xgr-network/xgr-node/validators"
)

var (
	MinValidatorCount = uint64(1)
	MaxValidatorCount = common.MaxSafeJSInt
)

// getAddressMapping returns the key for the SC storage mapping (address => something)
//
// More information:
// https://docs.soliditylang.org/en/latest/internals/layout_in_storage.html
func getAddressMapping(address types.Address, slot int64) []byte {
	bigSlot := big.NewInt(slot)

	finalSlice := append(
		common.PadLeftOrTrim(address.Bytes(), 32),
		common.PadLeftOrTrim(bigSlot.Bytes(), 32)...,
	)

	return keccak.Keccak256(nil, finalSlice)
}

// getIndexWithOffset is a helper method for adding an offset to the already found keccak hash
func getIndexWithOffset(keccakHash []byte, offset uint64) []byte {
	bigOffset := big.NewInt(int64(offset))
	bigKeccak := big.NewInt(0).SetBytes(keccakHash)

	bigKeccak.Add(bigKeccak, bigOffset)

	return bigKeccak.Bytes()
}

// getStorageIndexes is a helper function for getting the correct indexes
// of the storage slots which need to be modified during bootstrap.
//
// It is SC dependant, and based on the SC located at:
// https://github.com/0xPolygon/staking-contracts/
func getStorageIndexes(validator validators.Validator, index int) *StorageIndexes {
	storageIndexes := &StorageIndexes{}
	address := validator.Addr()

	// mapping(address => Staker) _staker is at slot 3
	stakerBase := getAddressMapping(address, stakerSlot)

	storageIndexes.StakerPackedIndex = stakerBase
	storageIndexes.StakerAmountIndex = getIndexWithOffset(stakerBase, 1)
	storageIndexes.StakerValidatorIndex = getIndexWithOffset(stakerBase, 4)
	storageIndexes.StakerBlsPubKeyIndex = getIndexWithOffset(stakerBase, 5)

	// _validators dynamic array is at slot 1
	storageIndexes.ValidatorsIndex = getIndexWithOffset(
		keccak.Keccak256(nil, common.PadLeftOrTrim(big.NewInt(validatorsSlot).Bytes(), 32)),
		uint64(index),
	)

	return storageIndexes
}

// setBytesToStorage sets bytes data into storage map from specified base index
func setBytesToStorage(
	storageMap map[types.Hash]types.Hash,
	baseIndexBytes []byte,
	data []byte,
) {
	dataLen := len(data)
	baseIndex := types.BytesToHash(baseIndexBytes)

	if dataLen <= 31 {
		bytes := types.Hash{}

		copy(bytes[:len(data)], data)

		// Set 2*Size at the first byte
		bytes[len(bytes)-1] = byte(dataLen * 2)

		storageMap[baseIndex] = bytes

		return
	}

	// Set size at the base index
	baseSlot := types.Hash{}
	baseSlot[31] = byte(2*dataLen + 1)
	storageMap[baseIndex] = baseSlot

	zeroIndex := keccak.Keccak256(nil, baseIndexBytes)
	numBytesInSlot := 256 / 8

	for i := 0; i < dataLen; i++ {
		offset := i / numBytesInSlot

		slotIndex := types.BytesToHash(getIndexWithOffset(zeroIndex, uint64(offset)))
		byteIndex := i % numBytesInSlot

		slot := storageMap[slotIndex]
		slot[byteIndex] = data[i]

		storageMap[slotIndex] = slot
	}
}

// PredeployParams contains the values used to predeploy the PoS staking contract
type PredeployParams struct {
	MinValidatorCount uint64
	MaxValidatorCount uint64
	EpochSize         uint64
}

// StorageIndexes is a wrapper for different storage indexes that
// need to be modified
type StorageIndexes struct {
	ValidatorsIndex      []byte // _validators[index]
	StakerPackedIndex    []byte // _staker[address].(exists,active,index packed)
	StakerAmountIndex    []byte // _staker[address].amount
	StakerValidatorIndex []byte // _staker[address].validator
	StakerBlsPubKeyIndex []byte // _staker[address].blsPubKey
}

// Slot definitions for SC storage
var (
	validatorThresholdSlot = int64(0) // slot0 VALIDATOR_THRESHOLD (uint256)
	configSlot             = int64(1) // slot1 packs epochSize|minNumValidators|maxNumValidators (uint64 each)
	validatorsSlot         = int64(2) // slot2 _validators dynamic array (self-validator stakers)
	stakerSlot             = int64(3) // slot3 mapping(address => Staker) _staker
	stakersSlot            = int64(4) // slot4 address[] _stakers
	validatorPoolSlot      = int64(5) // slot5 mapping(address => ValidatorPoolConfig) _poolConfig
	stakersByValidatorSlot = int64(6) // slot6 mapping(address => address[]) _stakersByValidator
	stakerIndexByValSlot   = int64(7) // slot7 mapping(address => mapping(address => uint256)) _stakerIndexPlusOneByValidator
)

const (
	// Bootstrap stake is liveness-only and must not alter chain economics.
	// Keep this at exactly 10 wei for PoA->PoS migration validators.
	DefaultStakedBalance = "0xA" // 10 wei
	//nolint: lll
	StakingSCBytecode = ""
)

func extractRuntimeBytecode(bytecode []byte) []byte {
	for i := 0; i+1 < len(bytecode); i++ {
		if bytecode[i] == 0xf3 && bytecode[i+1] == 0xfe {
			return bytecode[i+2:]
		}
	}

	return bytecode
}

// PredeployStakingSC is a helper method for setting up the staking smart contract account,
// using the passed in validators as pre-staked validators
func PredeployStakingSC(
	vals validators.Validators,
	params PredeployParams,
) (*chain.GenesisAccount, error) {
	if params.MaxValidatorCount == 0 {
		return nil, fmt.Errorf("invalid staking predeploy params: max validator count must be > 0")
	}

	if params.MinValidatorCount > params.MaxValidatorCount {
		return nil, fmt.Errorf("invalid staking predeploy params: min validator count (%d) exceeds max (%d)", params.MinValidatorCount, params.MaxValidatorCount)
	}

	if params.EpochSize < 2 {
		return nil, fmt.Errorf("invalid staking predeploy params: epoch size must be >= 2")
	}

	if vals != nil && uint64(vals.Len()) > params.MaxValidatorCount {
		return nil, fmt.Errorf("invalid staking predeploy params: validator set size (%d) exceeds max validator count (%d)", vals.Len(), params.MaxValidatorCount)
	}
	// Set the code for the staking smart contract
	// Code retrieved from https://github.com/0xPolygon/staking-contracts
	// and predeployed as runtime bytecode directly (constructor is NOT executed).
	scHex, _ := hex.DecodeHex(StakingSCBytecode)
	scHex = extractRuntimeBytecode(scHex)
	stakingAccount := &chain.GenesisAccount{
		Code: scHex,
	}

	// Parse the default staked balance value into *big.Int
	val := DefaultStakedBalance
	bigDefaultStakedBalance, err := common.ParseUint256orHex(&val)

	if err != nil {
		return nil, fmt.Errorf("unable to generate DefaultStatkedBalance, %w", err)
	}

	// Generate the empty account storage map
	storageMap := make(map[types.Hash]types.Hash)
	stakedAmount := big.NewInt(0)
	valsLen := big.NewInt(0)

	if vals != nil {
		valsLen = big.NewInt(int64(vals.Len()))

		for idx := 0; idx < vals.Len(); idx++ {
			validator := vals.At(uint64(idx))

			// Update the total staked amount
			stakedAmount = stakedAmount.Add(stakedAmount, bigDefaultStakedBalance)

			// Get the storage indexes
			storageIndexes := getStorageIndexes(validator, idx)

			// Set the value for the validators array
			storageMap[types.BytesToHash(storageIndexes.ValidatorsIndex)] =
				types.BytesToHash(
					validator.Addr().Bytes(),
				)

			if blsValidator, ok := validator.(*validators.BLSValidator); ok {
				setBytesToStorage(
					storageMap,
					storageIndexes.StakerBlsPubKeyIndex,
					blsValidator.BLSPublicKey,
				)
			}

			// pack exists=true (byte0), active=true (byte1), index(uint64) into slot
			packed := new(big.Int).SetUint64(uint64(idx))
			packed.Lsh(packed, 16)
			packed.Or(packed, big.NewInt(0x0101))
			storageMap[types.BytesToHash(storageIndexes.StakerPackedIndex)] = types.BytesToHash(packed.Bytes())

			// _staker[address].amount at base+1
			storageMap[types.BytesToHash(storageIndexes.StakerAmountIndex)] =
				types.StringToHash(hex.EncodeBig(bigDefaultStakedBalance))

			// _staker[address].joinedAtBlock at base+2
			storageMap[types.BytesToHash(getIndexWithOffset(storageIndexes.StakerPackedIndex, 2))] =
				types.BytesToHash(big.NewInt(1).Bytes())
			// _staker[address].validator at base+4 (self-validator bootstrap)
			storageMap[types.BytesToHash(storageIndexes.StakerValidatorIndex)] =
				types.BytesToHash(validator.Addr().Bytes())

			// _poolConfig[validator] at slot5: exists=true, active=true
			poolBase := getAddressMapping(validator.Addr(), validatorPoolSlot)
			storageMap[types.BytesToHash(poolBase)] = types.BytesToHash(big.NewInt(0x0101).Bytes())
			if blsValidator, ok := validator.(*validators.BLSValidator); ok {
				setBytesToStorage(storageMap, getIndexWithOffset(poolBase, 1), blsValidator.BLSPublicKey)
			}

			// _stakersByValidator[validator] = [validator]
			stakersByValBase := getAddressMapping(validator.Addr(), stakersByValidatorSlot)
			storageMap[types.BytesToHash(stakersByValBase)] = types.BytesToHash(big.NewInt(1).Bytes())
			stakersByValArrayBase := keccak.Keccak256(nil, common.PadLeftOrTrim(stakersByValBase, 32))
			storageMap[types.BytesToHash(getIndexWithOffset(stakersByValArrayBase, 0))] =
				types.BytesToHash(validator.Addr().Bytes())

			// _stakerIndexPlusOneByValidator[validator][validator] = 1
			stakerIndexOuter := getAddressMapping(validator.Addr(), stakerIndexByValSlot)
			stakerIndexInner := append(common.PadLeftOrTrim(validator.Addr().Bytes(), 32), common.PadLeftOrTrim(stakerIndexOuter, 32)...)
			storageMap[types.BytesToHash(keccak.Keccak256(nil, stakerIndexInner))] =
				types.BytesToHash(big.NewInt(1).Bytes())
		}
	}

	// Set slot2 _validators length
	storageMap[types.BytesToHash(big.NewInt(validatorsSlot).Bytes())] =
		types.BytesToHash(valsLen.Bytes())

	// Set slot4 _stakers length and values (self-staker list)
	storageMap[types.BytesToHash(big.NewInt(stakersSlot).Bytes())] =
		types.BytesToHash(valsLen.Bytes())
	stakersArrayBase := keccak.Keccak256(nil, common.PadLeftOrTrim(big.NewInt(stakersSlot).Bytes(), 32))
	if vals != nil {
		for idx := 0; idx < vals.Len(); idx++ {
			storageMap[types.BytesToHash(getIndexWithOffset(stakersArrayBase, uint64(idx)))] =
				types.BytesToHash(vals.At(uint64(idx)).Addr().Bytes())
		}
	}

	// Set slot0 VALIDATOR_THRESHOLD = MIN_STAKE = 2_000_000 ether.
	thresholdWei := new(big.Int).SetUint64(2_000_000)
	thresholdWei.Mul(thresholdWei, new(big.Int).Exp(big.NewInt(10), big.NewInt(18), nil))
	storageMap[types.BytesToHash(big.NewInt(validatorThresholdSlot).Bytes())] =
		types.BytesToHash(thresholdWei.Bytes())

	// Set packed slot1 (epochSize|minNumValidators|maxNumValidators, uint64 each).
	packedConfig := new(big.Int).SetUint64(params.MaxValidatorCount)
	packedConfig.Lsh(packedConfig, 64)
	packedConfig.Or(packedConfig, new(big.Int).SetUint64(params.MinValidatorCount))
	packedConfig.Lsh(packedConfig, 64)
	packedConfig.Or(packedConfig, new(big.Int).SetUint64(params.EpochSize))
	storageMap[types.BytesToHash(big.NewInt(configSlot).Bytes())] =
		types.BytesToHash(packedConfig.Bytes())

	// Save the storage map
	stakingAccount.Storage = storageMap

	// Set the Staking SC balance to numValidators * defaultStakedBalance
	stakingAccount.Balance = stakedAmount

	return stakingAccount, nil
}

// PredeployStakingSCBootstrap builds deterministic staking contract bootstrap state
// from the supplied validator set and predeploy parameters.
func PredeployStakingSCBootstrap(
	vals validators.Validators,
	params PredeployParams,
) (*chain.GenesisAccount, error) {
	return PredeployStakingSC(vals, params)
}

// IsUninitializedStakingStorage checks if staking storage has not been initialized yet.
// It must also treat "capacity set but validator list empty" as uninitialized,
// otherwise PoA->PoS bootstrap can skip and leave an empty contract-backed validator set.
func IsUninitializedStakingStorage(txn *state.Transition, addr types.Address) bool {
	if txn == nil {
		return true
	}

	zero := types.Hash{}

	// 1) capacity marker
	cfgKey := types.BytesToHash(big.NewInt(configSlot).Bytes())
	cfgH := txn.Txn().GetState(addr, cfgKey)
	if cfgH == zero || new(big.Int).SetBytes(cfgH[:]).Sign() == 0 {
		return true
	}

	// 2) validator list length (slot 1). If empty, treat as uninitialized.
	lenKey := types.BytesToHash(big.NewInt(validatorsSlot).Bytes())
	lenH := txn.Txn().GetState(addr, lenKey)
	if lenH == zero {
		return true
	}
	if new(big.Int).SetBytes(lenH[:]).Sign() == 0 {
		return true
	}

	// 3) epochSize (packed in slot1, lower uint64) must be initialized (>0) for unstake epoch math.
	cfg := new(big.Int).SetBytes(cfgH[:])
	epoch := cfg.Uint64()
	if epoch == 0 {
		return true
	}

	// 4) threshold (slot0) must be initialized (>0), constructor is not executed for predeploy.
	thresholdKey := types.BytesToHash(big.NewInt(validatorThresholdSlot).Bytes())
	thresholdH := txn.Txn().GetState(addr, thresholdKey)
	if thresholdH == zero || new(big.Int).SetBytes(thresholdH[:]).Sign() == 0 {
		return true
	}

	return false
}
